after.source_loop:
while level < afterstate.next_frontier.len() {
    if !super::pair_tree_profile::digest_is_canonical(&afterstate.next_frontier[level]) {
        return Err(PoolV1PairVerifierTransportErrorV1::NonCanonicalAfterstate);
    }
    level += 1;
}

after.one_iteration:
if level < frontier.len() {
    if !NBH_digest(&frontier[level]) {
        return (level, Some(PoolV1PairVerifierTransportErrorV1::NonCanonicalAfterstate));
    }
    level += 1;
}

after.prefix:
if afterstate.next_pair_index == 0 || afterstate.next_pair_index > crate::pool_v1::POOL_V1_PAIR_CAPACITY
{
    return Some(PoolV1PairVerifierTransportErrorV1::InvalidAfterstateIndex);
}
if !NBH_digest(&afterstate.next_root) {
    return Some(PoolV1PairVerifierTransportErrorV1::NonCanonicalAfterstate);
}

live.source_loop:
while level < snapshot.frontier.len() {
    if !digest_is_canonical(&snapshot.frontier[level]) {
        return Err(PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest);
    }
    level += 1;
}

live.one_iteration:
if level < frontier.len() {
    if !NBH_digest(&frontier[level]) {
        return (level, Some(PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest));
    }
    level += 1;
}

live.prefix:
if snapshot.pool == [0u8; 32] || snapshot.deployment_domain == [0u8; 32] {
    return Some(PoolV1PairLiveSnapshotErrorV1::ZeroRequiredBinding);
}
if snapshot.sequence != snapshot.next_pair_index {
    return Some(PoolV1PairLiveSnapshotErrorV1::SequenceIndexMismatch);
}
if snapshot.next_pair_index >= POOL_V1_PAIR_CAPACITY {
    return Some(PoolV1PairLiveSnapshotErrorV1::TreeFull);
}
if !NBH_digest(&snapshot.current_root) {
    return Some(PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest);
}
